"""Original service content and technical search metadata for HeyDock."""
import json,re,os
from html import escape,unescape
from pathlib import Path

def enrich(ns):
 page,hero,section,faq,cards,steps,link,pages=[ns[k] for k in ('page','hero','section','faq','cards','steps','link','pages')]
 # Each record is a distinct service enquiry, with supplier/capacity prerequisites visible.
 records=[
 ('managed-it-services','Managed IT support for businesses','managed IT support, outsourced IT services and co-managed IT support','Managed IT support combines an agreed helpdesk service with defined responsibility for maintaining the systems your team relies on. HeyDock scopes outsourced support for businesses and additional capacity for existing IT departments. The starting point is a review of users, devices, locations and current support arrangements.','Recurring faults, unclear support ownership and inconsistent device setup can absorb time across a growing team. A managed service creates an agreed route for requests, escalation and planned work. It should also identify what remains with your internal team or existing vendors. A monthly agreement is useful only when the supported environment and service limits are clear.',[
 ('Service desk and user support','Define how users report issues, which applications and devices are supported, and who owns each escalation. Requests can then be assessed by business impact rather than simply the order in which messages arrive.'),('Device and account lifecycle','Scope the joiner, mover and leaver process, including approved device setup, access changes and records. Clearly assigned approval responsibilities help avoid unnecessary access and missed handovers.'),('Maintenance and service review','Agree the monitoring, patching and reporting actually included in the contract. A review should look at recurring incidents, unresolved risks and upcoming business changes, not just ticket totals.')],
 'A growing office needs user support but already has a specialist managing its core application. A co-managed arrangement can give HeyDock responsibility for agreed desktop tasks while preserving the existing application escalation route. This is an illustrative engagement, not a customer case study.',
 [('Is managed IT support unlimited?','Only if a contract explicitly says so. Define users, devices, hours, included work and exclusions before comparing monthly fees.'),('Can we keep our internal IT team?','Yes. Co-managed support allocates responsibilities between your team and HeyDock, with escalation and change approval documented.')]),
 ('microsoft-365','Microsoft 365 support and migration','Microsoft 365 support, Microsoft 365 migration and Teams support','Microsoft 365 support helps organisations manage their productivity environment, user access and day-to-day collaboration. HeyDock can scope administration, onboarding and migration tasks for the workloads your business uses. Tenant access, licensing and specialist skills are confirmed before work starts.','Email and collaboration problems often affect several workflows at once. A mailbox migration, for example, is also an identity, device and communication project. Discovery should establish who owns the tenant, which subscriptions are in use and which integrations could be affected.',[
 ('Tenant and user administration','Agree authorised account administration, group membership and permission changes. Document who can approve new access and how requests are recorded. Do not share administrator credentials through ordinary enquiry forms.'),('Email and file migration','Map source data, permissions, retention needs and cutover dependencies before moving mailboxes or files. Test a representative migration and reconcile results before the wider change window.'),('Teams and collaboration','Review meeting, file-sharing and collaboration requirements alongside device and network readiness. Teams telephony is a separate scoped requirement with licensing and connectivity dependencies.')],
 'A business changing email platforms can begin with an inventory, migration pilot and user communication plan. The agreed scope identifies data that will move, downtime expectations, rollback options and post-migration checks.',
 [('Are licences included?','Licence supply and subscription costs are confirmed separately unless explicitly included in a proposal.'),('Are you claiming Microsoft partner status?','No partner accreditation is claimed on this page. Delivery capability and any vendor relationship should be evidenced for the engagement.')]),
 ('network-wifi','Business network and Wi-Fi support','network support, business Wi-Fi installation and network troubleshooting','Business network support covers the connectivity between users, devices, servers and cloud services. HeyDock scopes troubleshooting, network smart hands and planned infrastructure changes, including business and guest Wi-Fi requirements. The work is matched to your equipment, site and technical ownership.','Poor connectivity can have several causes: local wireless coverage, switching, configuration, cabling or an upstream service. A useful investigation separates symptoms from the underlying fault. It also records where your internal team, equipment vendor or connectivity supplier must take over.',[
 ('Fault investigation','Collect affected locations, devices, times and error behaviour. Compare wired and wireless access where relevant and work through the approved diagnostic plan before making changes.'),('Wireless planning','Assess coverage, capacity, building layout and the difference between employee and visitor access. Guest Wi-Fi should be scoped with appropriate isolation, access policy and support responsibilities.'),('Network changes and smart hands','Prepare the configuration owner, equipment, patching plan and change window. On-site engineers can perform authorised physical tasks while a remote specialist controls the network configuration.')],
 'An office with unreliable meeting-room Wi-Fi may need a survey and capacity review before buying replacement access points. A scoped assessment can identify whether coverage, interference, configuration or the upstream connection needs attention.',
 [('Can you install guest Wi-Fi?','Guest Wi-Fi requirements can be scoped, including equipment, segmentation, coverage and ongoing support.'),('Do you replace our internet provider?','Not automatically. Local network support and internet service supply are separate responsibilities and should be identified in the proposal.')]),
 ('backup-disaster-recovery','Backup and disaster recovery planning','business data backup, disaster recovery planning and backup restore testing','Backup and disaster recovery planning defines how business information and systems can be recovered after a failure. HeyDock can help scope backup configuration, restore testing and recovery documentation. The agreed service should identify what is protected, where copies are held and who acts when recovery is needed.','A backup job reporting success does not establish that an entire business service can be recovered. Recovery depends on usable data, application configuration, access, dependencies and available infrastructure. Planning should therefore connect technical backups to the actual order in which your team needs services restored.',[
 ('Protection scope','List systems, data sources and retention requirements. Identify cloud services that may need a separate backup arrangement, and record ownership of backup subscriptions and administrative access.'),('Restore tests','Choose representative files or workloads, restore them into an appropriate environment and check usability. Record the test result, elapsed time, gaps and the person responsible for corrective action.'),('Recovery runbooks','Define the recovery sequence, decision-makers and communications. Agree recovery-time and recovery-point objectives with the business before treating them as service commitments.')],
 'A company replacing its file server can include a restore test before migration and a recovery checkpoint before cutover. This connects the migration plan to a tested fallback rather than relying only on the existence of a backup.',
 [('Does backup guarantee no data loss?','No. Recovery depends on the protection design, backup frequency, failures and tested restore capability. Objectives and limitations must be agreed.'),('Can you review existing backups?','An assessment can review coverage, access, retention, restore evidence and gaps, subject to authorised access.')]),
 ('cybersecurity','Business cybersecurity support','business cybersecurity support, endpoint security and access security','Cybersecurity support helps businesses identify and improve the controls around devices, accounts and information. HeyDock can scope practical security work alongside IT support, including access reviews, endpoint controls and remediation projects. Specialist testing or incident services require the appropriate verified expertise and separate scope.','Security work should start with the systems, people and information at risk. Buying a tool without clear ownership can leave gaps in configuration, alerts and response. An effective engagement identifies the controls to implement, the evidence needed and who maintains them after handover.',[
 ('Identity and endpoint controls','Review administrative access, multi-factor authentication, device protection and supported configurations. Any changes must account for business applications and recovery access.'),('Remediation and configuration','Prioritise agreed findings and document changes, testing and exceptions. Maintenance responsibilities matter: a one-time improvement does not replace ongoing patching and account management.'),('Readiness and specialist coordination','Certification readiness, vulnerability assessment and incident response can be discussed as distinct workstreams. Certification assessment, penetration testing or a 24-hour security operations centre are not implied by general IT support.')],
 'A business with inconsistent employee onboarding can start by reviewing account approvals, administrator rights and offboarding. A scoped improvement may reduce avoidable access gaps without turning the project into an unsupported claim of complete protection.',
 [('Can you issue Cyber Essentials certification?','No assessor status is claimed. Readiness assistance and an authorised certification assessment are different services.'),('Is round-the-clock security monitoring included?','Only where an explicitly agreed service, qualified delivery team and operating arrangements provide it.')]),
 ('data-centre-support','Data centre smart hands and support','data centre smart hands, rack and stack and on-site infrastructure support','Data centre smart hands provides physical assistance where the remote technical team cannot attend. HeyDock can scope authorised checks, equipment handling, patching and documented site tasks. Facility access, equipment details, engineer competence and the change process must be confirmed before dispatch.','A data centre visit is not a general desktop call-out. Work may affect shared infrastructure or production services, so the task list and escalation path need to be precise. A remote technical owner should identify what the engineer can do independently and which steps require explicit approval.',[
 ('Physical checks and evidence','Record the rack, device identifiers, port labels and requested observations. Photographs and serial-number records should follow site rules and avoid unnecessary exposure of sensitive information.'),('Equipment and patching tasks','Scope rack installation, component handling or cable changes with the correct tools, parts, lifting arrangements and authorised method. Electrical and specialist facility work requires suitable permissions and competence.'),('Controlled change support','Agree pre-change checks, the change window, expected results and rollback instructions. Stop and escalate if the equipment or site conditions do not match the approved work order.')],
 'A remote infrastructure team may need an engineer to identify a device, confirm indicator status and perform an approved cable change. The work order provides exact identifiers and a live escalation contact before attendance.',
 [('Can you attend any data centre immediately?','Access rules, geography, skills and availability must be confirmed. There is no universal immediate attendance commitment.'),('Who owns configuration changes?','The approved scope identifies the configuration owner. Smart hands attendance alone does not authorise unplanned changes.')]),
 ('it-rollouts-migrations','IT rollouts and office migrations','IT rollout services, desktop deployment and office IT relocation','IT rollouts and migrations coordinate repeatable technical changes across users, devices or sites. HeyDock scopes device refreshes, software deployments, office IT moves and related migration work with agreed testing and handover. A successful rollout begins with a dependable inventory and a pilot.','Large changes become manageable when the process is repeatable. Before scheduling engineers, establish which devices are included, which configuration is approved and how exceptions will be handled. A small pilot can expose access, application or timing issues before they affect the wider rollout.',[
 ('Preparation and inventory','Record assets, users, locations, applications and dependencies. Confirm delivery dates, available stock, software rights and the information needed to configure each device.'),('Pilot and deployment waves','Test the process with representative users, then organise waves around business availability. Record exceptions and completion status so incomplete tasks do not disappear into a simple device count.'),('Migration and handover','Agree backup checkpoints, data validation, user communication and support after cutover. Update asset records and retain evidence that the user or site meets acceptance criteria.')],
 'A multi-site laptop refresh can use a common build, site-specific booking windows and an exception queue. The final report distinguishes deployed devices from devices awaiting access, parts or user acceptance.',
 [('Can you work with our existing deployment process?','Yes. The work can follow your approved build, tooling and reporting requirements after review.'),('Is data migration automatically included?','No. Data volumes, sources, permissions, validation and recovery must be explicitly scoped.')]),
 ('hardware-break-fix','Hardware maintenance and break-fix support','IT break-fix support, hardware maintenance and desktop repair coordination','Break-fix support addresses a specific fault with a device or related equipment. HeyDock scopes diagnosis, approved replacement tasks and escalation for business hardware. Parts, warranty rights, supported models and whether repair is practical are checked before a commitment is made.','The quickest useful response is often a structured diagnosis rather than immediately replacing equipment. The engineer needs symptoms, asset details and what has already been tried. For business-critical devices, the temporary workaround and data protection requirements can be as important as the repair itself.',[
 ('Fault diagnosis','Document the behaviour, affected accessories, recent changes and available error information. Separate hardware faults from operating-system, application and connectivity issues where possible.'),('Replacement planning','Confirm compatible parts, warranty restrictions, stock and authority to replace. A visit does not guarantee that the required part is available or that repair is economical.'),('Validation and asset records','Test the repaired or replacement device against the agreed use case. Record component changes, unresolved issues, data handling and handover to the user or support team.')],
 'A failed office workstation may require a loan device before a component replacement. A useful work order separates restoring user productivity from completing the permanent repair.',
 [('Are replacement parts included in the visit price?','Only when listed in the quotation. Diagnosis, labour, parts, shipping and return handling can be separate items.'),('Can you repair every brand and model?','Supported equipment and engineer skills are confirmed for each request.')]),
 ('it-asset-disposal','IT asset retirement and disposal coordination','IT asset disposal coordination, IT decommissioning and equipment retirement','IT asset retirement covers taking equipment out of service, recording ownership and arranging appropriate data handling and disposition. HeyDock can scope decommissioning and coordinate the required disposal route. Collection, sanitisation and recycling obligations are confirmed with the responsible delivery organisations.','Retirement starts before a device leaves the site. Establish what it contains, whether data must be retained and who can authorise its release. A disposal project should maintain traceability from the asset list to the final evidence rather than treating collection as completion.',[
 ('Inventory and release approval','Match serial numbers, ownership and retention decisions. Check leases, finance arrangements and vendor return obligations before assuming an asset may be disposed of.'),('Data handling and chain of custody','Agree the sanitisation or destruction method, responsible party, transport controls and evidence required. Do not release equipment without an authorised process for the information it holds.'),('Final records','Reconcile collected assets with the agreed list, record exceptions and retain the relevant destruction or recycling evidence. The exact certifications and documentation depend on the chosen delivery route.')],
 'An office closure may combine asset recovery, data retention and equipment disposal. Separating reuse, return and disposal items helps prevent serviceable or leased equipment entering the wrong stream.',
 [('Are you a certified recycling or destruction provider?','No specific waste-carrier, recycling or destruction certification is claimed here. The necessary provider credentials and process must be verified before work.'),('Can disposal be combined with a refresh project?','Yes, where collection, data handling, ownership and reporting are included in the approved scope.')]),
 ('meeting-room-av','Meeting room and AV support','meeting room AV support, video conferencing support and Teams room assistance','Meeting room support addresses the devices and connections needed for calls, presentations and collaboration. HeyDock can scope checks, installation assistance and troubleshooting for supported audio-visual equipment. Room platforms, cabling, network access and manufacturer requirements are reviewed before work begins.','A meeting problem can originate in the room device, a user laptop, permissions, audio routing or connectivity. Reproducing the problem with the actual conferencing platform helps avoid changing equipment unnecessarily. The scope should also distinguish everyday user assistance from a specialist AV installation.',[
 ('Room readiness checks','Review displays, microphones, cameras, peripherals and the expected connection path. Test the room against the meeting types the business actually uses.'),('Installation and configuration assistance','Scope equipment setup, cable management and authorised application configuration. Mounting, electrical work or advanced room design requires suitable specialist arrangements.'),('User guidance and handover','Document how to start meetings, share content and report faults. A short usable room guide can reduce repeated support requests after installation.')],
 'A business introducing hybrid meeting rooms can pilot one room, record common connection issues and use the findings to standardise the remaining installations.',
 [('Do you support Teams or other meeting platforms?','Platform and equipment support is confirmed for the engagement, including licensing and administrative access.'),('Can you supply the equipment?','Equipment sourcing can be discussed separately from installation and support, with compatibility and warranty terms confirmed.')]),
 ('business-connectivity-telephony','Business connectivity and cloud telephony','business broadband, leased-line coordination, VoIP and cloud phone systems','Business connectivity and telephony projects connect premises, people and customer conversations. HeyDock can scope requirements and coordinate suitable broadband, leased-line, mobile connectivity and cloud-phone options. Supplier availability, contracts, installation dates and service responsibilities are confirmed before any order.','An internet or telephone change affects more than a monthly bill. Consider application use, voice quality, resilience, number ownership and how users will work during migration. A supplier delivery date is not the same as a fully tested business-ready service.',[
 ('Connectivity requirements','Review sites, users, applications, upload needs and resilience. Compare available access types against the actual location and business requirements instead of assuming the same service is available everywhere.'),('Cloud phones and contact workflows','Map numbers, call routing, users, devices and customer support requirements. Number porting, emergency calling arrangements and licensing need specific attention in the selected service.'),('Cutover and supplier coordination','Agree the install schedule, migration sequence, testing and fallback. Identify which organisation owns the circuit or platform and where faults will be escalated.')],
 'An office move may need a temporary connection while a permanent service is installed. The project plan should test the fallback against real application and calling needs before the move date.',
 [('Do you operate a telecom network?','No network-operator status is claimed. Service availability and supply arrangements are established through the relevant providers.'),('Can you help with business mobiles and SIM requirements?','Mobile connectivity, device and SIM requirements can be assessed as part of a scoped connectivity project.')]),
 ('it-consultancy','IT consultancy and site surveys','IT consultancy, IT site surveys and technology planning','IT consultancy helps a business turn a technology problem into an achievable plan. HeyDock scopes site assessments, infrastructure reviews and project discovery, with a focus on decisions the business needs to make. A site survey records the agreed observations; it does not automatically certify every system.','A useful assessment begins with a question. You may be planning an office move, replacing equipment or deciding whether a software project is viable. Defining the decision first keeps the survey focused on relevant evidence rather than collecting an inventory that nobody uses.',[
 ('Discovery and current-state review','Gather business goals, affected users, existing systems and constraints. Identify what information is missing and which stakeholders can validate the findings.'),('Site and infrastructure observations','Record relevant equipment, connectivity, space and access requirements. Agree survey depth, site permissions and any specialist testing before attendance.'),('Options and implementation planning','Present practical options, dependencies and assumptions. Separate recommendations from confirmed scope, and identify what needs further validation before a delivery commitment.')],
 'Before an office relocation, a survey can assess desk capacity, network points, meeting rooms and connectivity dependencies. The findings become an implementation brief with owners and an agreed sequence.',
 [('What do we receive after an assessment?','The scope can include findings, an inventory, identified gaps and recommended next steps. Required report formats should be agreed upfront.'),('Can you deliver the resulting project?','Implementation can be proposed separately once the requirements, capacity and costs are confirmed.')])]
 for slug,title,keywords,answer,context,features,example,faqs in records:
  body=hero('BUSINESS IT SERVICES',title+'.',answer,'Discuss requirements','/contact.html?service='+slug)
  body+=section('SERVICE EXPLAINED','What does this service involve?','', '<div class="prose"><p>'+context+'</p><p>The engagement starts by identifying the business outcome, existing responsibilities and the changes you authorise. HeyDock then confirms suitable delivery capacity, the working window and the evidence needed to complete the task. Related licences, hardware, subscriptions and specialist services are included only where the proposal says so.</p></div>')
  body+=section('PRACTICAL SCOPE','What can be included?','The final statement of work identifies the tasks that apply to your environment.','<div class="rich-features">'+''.join('<article><h3>'+t+'</h3><p>'+d+'</p></article>' for t,d in features)+'</div>','pale')
  body+=section('EXAMPLE REQUIREMENT','How a project might work.','', '<div class="prose"><p>'+example+'</p></div>')
  body+=section('PLANNING AND COST','What affects the scope and price?','', '<div class="prose"><p>Cost depends on the number of users, devices or sites; technical complexity; access requirements; delivery hours; travel; and the work needed before and after implementation. Provide relevant system versions and existing supplier responsibilities so the quotation can distinguish labour from licences, equipment and recurring charges.</p><p>For a well-defined task, a visit or project quotation may be appropriate. Where important dependencies are unknown, a paid assessment can produce a better implementation scope. Any response, attendance or recovery target must be explicitly agreed; requesting a service does not create an immediate support commitment.</p></div>')
  body+=section('COMMON QUESTIONS',title+' FAQs','',faq(faqs+[('What information should we include in an enquiry?','Describe the objective, location, affected systems, preferred timing and existing support arrangements. Do not send passwords or sensitive business records in the enquiry form.')]))
  body+=section('RELATED SUPPORT','Connect this work to the wider plan.','',cards([('/it-support.html','IT support','User, desktop and remote support for your environment.','screen'),('/engineer-dispatch.html','Engineer dispatch','Local attendance for authorised technical tasks.','pin'),('/how-we-work.html','Delivery approach','Scope, change control, acceptance and handover.','clipboard')]))
  page(slug+'.html',title,answer[:155],body,'/services.html')
 # Add substantive original explanations to existing pages.
 expansions={
 'index.html':('IT support, software and AI automation for businesses','HeyDock provides technology services for businesses and IT partners. We work with direct business customers and IT providers that need additional delivery capacity. Our offering combines on-site engineering, remote technical resources, ready-made business software, custom development and AI automation. The engagement may be a single authorised site visit, a software implementation or an ongoing service with defined responsibilities.','For business teams, the first question is usually what needs to work better: employee devices, customer support, internal processes or disconnected applications. For IT partners, it may be engineering availability, a rollout deadline or a customer location outside the existing team’s reach. Those are different buying needs, so our service pages explain the delivery model, prerequisites and questions to resolve before starting.','Our UK and European coverage is based on available engineers and confirmed requirements. Remote services can extend the available options, but working hours, data access and technical skills still need to match the job. We do not substitute broad geographical claims for a confirmed site booking.'),
 'it-support.html':('What is included in business IT support?','Business IT support helps users operate their devices and applications and provides a route for diagnosing technical problems. HeyDock scopes end-user computing support, desktop troubleshooting, remote assistance and on-site tasks for agreed environments. Support can complement an internal team or cover defined responsibilities for a business without its own helpdesk.','A useful support request states the affected device, application, error and business impact. For example, a printer issue for one employee is different from an office-wide inability to access a shared system. The support process should distinguish initial response, technical diagnosis, engineer attendance and resolution; these are not interchangeable promises.','Desktop support can involve peripherals, approved application setup, device imaging or re-imaging, mobile device assistance and user onboarding. These tasks depend on authorised access, supported platforms and a clear record of the intended configuration. Where the issue belongs to an application vendor or connectivity supplier, the escalation route should be identified rather than leaving the user between teams.'),
 'engineer-dispatch.html':('How does IT engineer dispatch work?','IT engineer dispatch assigns an on-site technical resource to a defined work order. The customer or service provider supplies the location, task, access window and escalation contact. HeyDock checks the required skills and availability before confirming attendance and the commercial terms. This model is useful for remote IT teams that need physical assistance at a customer site.','Dispatch work can include desktop break-fix, approved hardware changes, network patching, equipment checks and rollout assistance. The engineer needs exact device or site identifiers and an understanding of which changes are authorised. If conditions differ from the work order, the next step is to document and escalate the difference rather than improvise a production change.','A complete visit report records arrival and departure, tasks performed, test results, outstanding issues and customer sign-off where applicable. Photographs or asset information should follow the customer’s information-handling rules. For repeated work across several locations, a common checklist and exception process make the programme easier to manage.'),
 'remote-talent.html':('Remote staffing or managed delivery: which do you need?','Remote technical staffing adds agreed expertise to a customer-directed team. Managed delivery gives HeyDock responsibility for the process and agreed outputs. Both models can involve remote engineers, software developers, testers, AI specialists or customer support staff, but supervision and accountability differ. The contract should reflect how the work will actually operate.','A role brief should describe the technology stack, skill level, language, working hours, reporting line and expected tasks. It should also identify the equipment and secure access needed to work. Candidate review can then focus on relevant skills rather than a generic job title that means different things to different teams.','Remote chat and customer support need approved knowledge, escalation and quality review. An engineer working on infrastructure needs clear permissions and change control. A developer needs repository access, acceptance criteria and a release process. Agreeing these details before onboarding helps the specialist contribute without unnecessary access or ambiguous responsibilities.'),
 'custom-software.html':('Custom software development and website delivery','Custom development is useful when an existing product cannot reasonably support an important business workflow. HeyDock can scope internal applications, customer portals, integrations and websites, beginning with the users and outcomes rather than a list of technologies. Where requirements remain uncertain, discovery should produce a documented specification and implementation options.','Website development includes information architecture, page content, responsive layouts and useful enquiry journeys. A transactional application has additional requirements such as identity, data storage, permissions and operational monitoring. A simple marketing site does not need the same architecture as a multi-user business platform; the stack should fit the functionality and maintenance model.','Software delivery also includes testing, deployment, documentation and ownership decisions. Agree who controls hosting accounts, repositories and domains, which components are licensed, and what support starts after acceptance. Changes to scope should be assessed for impact on cost and timing. Source-code access and intellectual property should be explicit rather than assumed.'),
 'ai-automation.html':('What can AI automation do for a business?','AI automation combines a model’s ability to interpret or generate information with a controlled business workflow. Examples include drafting support replies, finding approved knowledge, extracting information from documents and routing a task to the right team. A chatbot is one possible interface; a useful automation may also operate behind an internal form or service desk.','The starting point should be a task that can be measured. Record the current process, typical exceptions and the quality threshold. Then choose the data sources, model or tools and approval points. Testing must include cases where the assistant should decline an action, ask for clarification or hand the work to a person. A plausible answer is not the same as a correct business outcome.','Production readiness includes cost limits, provider outages, data retention, permissions and monitoring. Keep privileged actions within a specifically authorised workflow. A customer-facing assistant should have a clear escalation path when it cannot answer reliably. Changes to the model, knowledge sources or connected systems may require new evaluation rather than treating the initial pilot as permanent proof.'),
 'software.html':('Ready-made software versus custom development','Ready-made business software provides an existing platform that can be configured for a defined workflow. HeyDock offers implementation discussions for HR, small-business ERP, ticketing, booking and appointment systems, with additional solutions assessed against your requirements. The catalogue describes solution categories; the selected product, licence and supported features are confirmed during discovery.','An implementation includes more than installing an application. Data needs to be prepared and validated, users need appropriate access, and integrations must be tested. Hosting, backups, renewals and support responsibilities should be agreed before launch. A short product demonstration is useful, but it should use representative tasks and a clear evaluation checklist.','Choose custom development when the required process is genuinely distinctive or the integration gap cannot be sensibly addressed through configuration. Choose an existing platform when its supported workflow meets the need at an acceptable total cost. The comparison should include maintenance and exit costs, not just the initial build or licence price.'),
 'partners.html':('White-label IT support for MSPs and IT service providers','White-label delivery lets an IT company retain its customer relationship while using HeyDock for agreed engineering or technical capacity. It can support local attendance, deployment programmes and remote assignments. The operating model defines branding, end-customer communication and reporting before the first visit or assignment.','Vendor onboarding should establish the legal parties, relevant capability evidence, insurance requirements, confidentiality and data access. Each work order then identifies the task, site, service window and escalation route. This keeps commercial responsibility and technical authorisation clear across the delivery chain.','For ongoing partnerships, review the quality of completion reports, avoidable repeat visits, open exceptions and upcoming demand. Capacity should be confirmed against real requirements rather than assumed from a broad coverage map. A service-level commitment only works when the required people, access and parts can actually support it.'),
 'coverage.html':('UK on-site support and European engineering coverage','HeyDock has engineers in the UK and Europe and scopes attendance against the customer’s actual location. Availability depends on the city, required skill, site access, work window and travel arrangements. We do not list offices in cities where a physical business location has not been confirmed.','For cross-border work, agree language, time zone, site rules and contracting arrangements before scheduling. Remote assistance may solve part of the requirement, while a local engineer handles the physical tasks. A combined approach is often useful for network smart hands, equipment checks and repeatable deployments.','Global delivery is an expansion objective, not a claim of unrestricted worldwide on-site coverage. Share the location and work order so available options can be confirmed. Multiple sites should be listed separately where skills, access or service expectations differ.'),
 'solutions.html':('Choosing IT services around business needs','A direct business customer may need support for a single problem or a broader improvement programme. HeyDock’s service model covers people, infrastructure, software and automation, allowing the work to be scoped around the operational issue. The first step is to identify the affected team and the result that would make the engagement successful.','An office may need reliable device onboarding and collaboration tools. A service business may need booking, appointment or ticketing workflows. A growing operation may need an ERP implementation or an integration between existing systems. These are examples of requirements to discuss, not claims of completed sector-specific projects.','Where several services are involved, define ownership across them. A new application may depend on network access, data migration and staff training. A customer-support chatbot may depend on an accurate knowledge base and a human escalation route. A joined-up plan makes those dependencies visible before delivery starts.')}
 for path,(title,*paras) in expansions.items():
  block=section('IN MORE DETAIL',title,'','<div class="prose">'+''.join('<p>'+p+'</p>' for p in paras)+'</div>')
  t,m=pages[path];pages[path]=(t,m.replace('</main>',block+'</main>'))
 # Product-specific implementation detail, with no invented product specifications.
 for p in ns['catalog']:
  path='software/'+p['slug']+'.html'
  block=section('IMPLEMENTATION GUIDE','What to check before choosing '+p['name'].lower(),'', '<div class="prose"><p>'+p['fit']+' Start by documenting the process you want the system to support, including exceptions and approval decisions. A clear process map makes it easier to assess whether the selected product supports the work through configuration or needs additional development.</p><h3>Evaluate the workflow with real requirements</h3><p>Use representative, approved sample data to walk through the important tasks. Ask how users find information, how permissions differ by role and what happens when a record is incomplete or a request changes. Record gaps rather than assuming that a feature name proves the workflow will work for your team.</p><h3>Plan data migration and integrations</h3><p>Identify the source records, duplicates, required fields and ownership of data cleanup. Define how completeness and accuracy will be checked after migration. Integrations need a documented interface, error handling and a clear owner when a connected service is unavailable. Do not assume an integration is included until the selected product and scope confirm it.</p><h3>Understand cost and operational ownership</h3><p>Separate subscription or licence fees from implementation, hosting, migration, training and ongoing support. Confirm who administers users and who applies updates. Ask how to export records if the business later changes platform. Ownership of the underlying software, licence conditions and source access are recorded in the commercial agreement.</p><h3>Accept and hand over the system</h3><p>Agree user acceptance tests before release. The final handover should identify the configured workflows, known limitations, administrator responsibilities and support route. A pilot with a representative team can expose training needs before the wider business starts using the system.</p></div>')
  t,m=pages[path];pages[path]=(t,m.replace('</main>',block+'</main>'))
 # Link all new pages through the service hub and home; no orphan keyword pages.
 hub=section('SPECIALIST SERVICE AREAS','Explore the full service scope.','Discuss the requirement with HeyDock. Specialist capacity, supplier arrangements and any required credentials are confirmed before delivery.',cards([('/'+s+'.html',t,a[:145]+'…',{'managed-it-services':'headset','microsoft-365':'grid','network-wifi':'network','backup-disaster-recovery':'backup','cybersecurity':'shield','data-centre-support':'server','hardware-break-fix':'tools','it-rollouts-migrations':'deploy','business-connectivity-telephony':'phone','meeting-room-av':'camera','it-asset-disposal':'recycle','it-consultancy':'compass'}.get(s,'code')) for s,t,k,a,*rest in records]))
 for path in ('services.html',):
  t,m=pages[path];pages[path]=(t,m.replace('</main>',hub+'</main>'))
 # Improve target titles while leaving brand-led headings visible.
 titles={'index.html':'Business IT Support, Software & AI Automation UK','it-support.html':'Business IT Support & Desktop Support UK','engineer-dispatch.html':'IT Engineer Dispatch & White Label Field Support','remote-talent.html':'Remote IT Engineers & Technical Staffing','custom-software.html':'Custom Software & Business Website Development','ai-automation.html':'AI Automation, Agents & Customer Support Chatbots','partners.html':'White Label IT Support for MSPs & IT Providers','coverage.html':'UK & European IT Engineering Coverage'}
 # Keep detailed service enquiry routes available in the form.
 t,m=pages['contact.html']
 options=''.join('<option value="'+r[0]+'">'+escape(r[1])+'</option>' for r in records)
 m=m.replace('<option value="coverage">',options+'<option value="coverage">')
 pages['contact.html']=(t,m)
 origin=os.environ.get('HEYDOCK_ORIGIN','https://nexorvanta-business-preview.sproutingbadge2.chatgpt.site').rstrip('/')
 public=os.environ.get('HEYDOCK_PUBLIC')=='1'
 if public and ('chatgpt.site' in origin or not origin.startswith('https://')):raise ValueError('Public builds require HEYDOCK_ORIGIN set to your HTTPS production domain')
 org={'@type':'Organization','@id':origin+'/#organization','name':'HeyDock','url':origin+'/','description':'IT services, software implementation, technical staffing and AI automation.'}
 def plain(x):return ' '.join(unescape(re.sub('<[^>]+>',' ',x)).split())
 urls=[];report=[]
 for path,(title,m) in list(pages.items()):
  title=titles.get(path,title);url=origin+('/' if path=='index.html' else '/'+path)
  m=re.sub(r'<title>.*?</title>','<title>'+escape(title)+' | HeyDock</title>',m,count=1)
  m=re.sub(r'<meta property="og:title" content="[^"]*">','<meta property="og:title" content="'+escape(title,quote=True)+' | HeyDock">',m,count=1)
  description=re.search(r'<meta name="description" content="([^"]*)"',m).group(1)
  if path!='index.html':
   crumb = (
    '<div class="breadcrumb-bar"><div class="wrap breadcrumbs" role="navigation" aria-label="Breadcrumb">'
    '<a href="/">Home</a><span aria-hidden="true">/</span>'
    '<span aria-current="page">'+escape(title)+'</span></div></div>'
   )
   m=m.replace('</header>','</header>'+crumb,1)
  graph=[org,{'@type':'WebSite','@id':origin+'/#website','url':origin+'/','name':'HeyDock','publisher':{'@id':org['@id']}},{'@type':'WebPage','@id':url+'#page','url':url,'name':title,'description':unescape(description),'isPartOf':{'@id':origin+'/#website'},'about':{'@id':org['@id']},'inLanguage':'en-GB'}]
  if path!='index.html':graph.append({'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Home','item':origin+'/'},{'@type':'ListItem','position':2,'name':title,'item':url}]})
  if path in [r[0]+'.html' for r in records]+[x+'.html' for x in ns['data']]:graph.append({'@type':'Service','@id':url+'#service','name':title,'description':unescape(description),'provider':{'@id':org['@id']},'url':url})
  # Mark up only FAQs actually rendered, with exact answer text. No ratings or claims.
  questions=[]
  for q,a in re.findall(r'<details><summary>(.*?)<span aria-hidden="true">\+</span></summary><p>(.*?)</p></details>',m,re.S):questions.append({'@type':'Question','name':plain(q),'acceptedAnswer':{'@type':'Answer','text':plain(a)}})
  if questions:graph.append({'@type':'FAQPage','@id':url+'#faq','mainEntity':questions})
  robots='index, follow, max-image-preview:large' if public and path!='404.html' else 'noindex, nofollow'
  tags='<link rel="canonical" href="'+url+'"><meta property="og:url" content="'+url+'"><meta property="og:type" content="website"><meta property="og:site_name" content="HeyDock"><meta name="robots" content="'+robots+'"><script type="application/ld+json">'+json.dumps({'@context':'https://schema.org','@graph':graph}).replace('<','\\u003c')+'</script>'
  m=m.replace('</head>',tags+'</head>');pages[path]=(title,m)
  if path!='404.html':urls.append(url)
  main=re.search(r'<main.*?</main>',m,re.S).group();report.append({'page':path,'main_words':len(plain(main).split()),'faq_count':len(questions),'title':title})
 Path('content/search-build.json').write_text(json.dumps({'origin':origin,'public_indexing':public,'pages':report},indent=2))
 Path('dist/sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+escape(u)+'</loc></url>' for u in urls)+'</urlset>')
 # build.py owns final robots; save public configuration for its final line.
 ns['seo_public']=public;ns['seo_origin']=origin
